import{_ as r}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as t,o as e,c as l,a3 as i}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"欢迎","description":"MiniTavern Ultra（超迷你酒馆）用户手册：一句话建卡与角色卡 v2/v3，GPT、Claude、OpenRouter 或本地模型，世界书、正则、预设、识图识人与回复图片，备份和聊天存档。","frontmatter":{"title":"欢迎","description":"MiniTavern Ultra（超迷你酒馆）用户手册：一句话建卡与角色卡 v2/v3，GPT、Claude、OpenRouter 或本地模型，世界书、正则、预设、识图识人与回复图片，备份和聊天存档。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色卡v2,角色卡v3,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,预设,识图,识人,回复图片,GPT,Claude,OpenRouter,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"欢迎 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra（超迷你酒馆）用户手册：一句话建卡与角色卡 v2/v3，GPT、Claude、OpenRouter 或本地模型，世界书、正则、预设、识图识人与回复图片，备份和聊天存档。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792058564000}'),n={name:"index.md"};function o(u,a,s,d,g,h){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="欢迎" tabindex="-1">欢迎 <a class="header-anchor" href="#欢迎" aria-label="Permalink to &quot;欢迎&quot;">​</a></h1><div class="overview-hero"><p><img src="'+r+'" alt="MiniTavern Ultra 功能界面展示"></p></div><h2 id="应用简介" tabindex="-1">应用简介 <a class="header-anchor" href="#应用简介" aria-label="Permalink to &quot;应用简介&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong>（超迷你酒馆）是一款 <strong>AI 角色扮演聊天应用</strong>。</p><p><strong>创造你的伙伴，开始你们的故事</strong>——一句话生成角色卡，或把主流 v2、v3 卡带进来。</p><p>GPT、Claude、OpenRouter 和家里的本地模型都能接。密钥留在手机里，聊天也优先留在本机。</p><h2 id="你可以做什么" tabindex="-1">你可以做什么 <a class="header-anchor" href="#你可以做什么" aria-label="Permalink to &quot;你可以做什么&quot;">​</a></h2><ol><li><p><strong>一句话创建角色卡，或带进 v2 / v3</strong><br> 描述想要的人，生成名称、人设和开场白，预览后开聊。见 <a href="/ultra_guides/manual/ai-create">AI 创建</a>。PNG / JSON 对齐主流角色卡 v2、v3，见 <a href="/ultra_guides/manual/chara-card">角色卡</a>。</p></li><li><p><strong>接 GPT、Claude、OpenRouter，或本地模型</strong><br> 自备密钥直连这些平台，也能接 Ollama / LM Studio。密钥放在本机安全存储。见 <a href="/ultra_guides/manual/model-link">模型连接</a>。没有付费额度时见 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机部署见 <a href="/ultra_guides/local/">部署本地模型</a>。</p></li><li><p><strong>世界书、正则、预设：创建或导入</strong><br><a href="/ultra_guides/manual/lorebook">世界书</a> 稳住设定，<a href="/ultra_guides/manual/regex">正则</a> 打磨呈现，<a href="/ultra_guides/manual/presets">预设</a> 换一整套提示词写法。都能新建，也能导入已有文件。采样仍在模型设置里。</p></li><li><p><strong>沉浸对话：识图、识人、回复图片</strong><br> 发出去的图能被看懂，也能认出画面里的人；角色可以按剧情把图片回复进聊天。见 <a href="/ultra_guides/manual/chat">聊天</a>。</p></li><li><p><strong>备份和聊天存档</strong><br><a href="/ultra_guides/manual/backup">全量备份</a> 把角色、聊天、世界书和正则换机带走，密钥是否打包由你决定。<a href="/ultra_guides/manual/chat-archive">聊天存档</a> 可合并进旧对话，或作为新聊天导入。</p></li></ol><h2 id="为什么是-minitavern" tabindex="-1">为什么是 MiniTavern <a class="header-anchor" href="#为什么是-minitavern" aria-label="Permalink to &quot;为什么是 MiniTavern&quot;">​</a></h2><ul><li><strong>建卡很快</strong>：一句话生成，或导入 v2 / v3</li><li><strong>模型自备</strong>：GPT、Claude、OpenRouter 或本地模型，密钥留在本机</li><li><strong>长线工具齐</strong>：世界书、正则、预设、人设，创建和导入都有</li><li><strong>对话能看图</strong>：识图、识人、回复图片</li><li><strong>每一聊单独配</strong>：模型、预设、世界书、正则和生图可按会话覆盖</li><li><strong>数据可带走</strong>：全量备份与单聊存档</li></ul><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li><strong>配置模型</strong>：设置 → <a href="/ultra_guides/manual/model-link">模型</a> → 模型连接 → 新建并测连，设为默认。</li><li><strong>导入或创造角色</strong>：角色卡 → <a href="/ultra_guides/manual/chara-card">导入或创建</a>。</li><li><strong>开始聊天</strong>：从角色开聊——陪伴或入戏，由你决定。</li></ol><p>更细步骤见 <a href="/ultra_guides/manual/getting-started">第一次使用</a>。本机部署见左侧 <strong>部署本地模型</strong>：<a href="/ultra_guides/local/">概览</a> · <a href="/ultra_guides/quickstart">语言模型通关</a> · <a href="/ultra_guides/local/image-gen/">生图</a>。免费额度见 <a href="/ultra_guides/free-cloud/">免费云端</a>。</p><h2 id="用户手册入口" tabindex="-1">用户手册入口 <a class="header-anchor" href="#用户手册入口" aria-label="Permalink to &quot;用户手册入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分区</th><th>说明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/manual/">手册首页</a></td><td>建议阅读顺序与总览</td></tr><tr><td><a href="/ultra_guides/manual/model-link">模型</a></td><td>连接、参数、测连与排错</td></tr><tr><td><a href="/ultra_guides/free-cloud/">免费云端</a></td><td>各厂商免费额度与填 Key</td></tr><tr><td><a href="/ultra_guides/local/">部署本地模型</a></td><td>语言 / 生图本机部署</td></tr><tr><td><a href="/ultra_guides/manual/chara-card">角色</a> · <a href="/ultra_guides/manual/ai-create">AI 创建</a></td><td>导入、编辑、开聊、用模型生成</td></tr><tr><td><a href="/ultra_guides/manual/chat">聊天</a> · <a href="/ultra_guides/manual/bubbles">气泡与输入框</a></td><td>对话、外观、会话设置</td></tr><tr><td><a href="/ultra_guides/manual/lorebook">进阶</a> · <a href="/ultra_guides/manual/presets">预设</a></td><td>世界书、正则、人设、预设</td></tr></tbody></table><p>App 内：设置 → <strong>帮助与反馈</strong> → <strong>用户手册</strong>。</p><h2 id="常见问题-摘要" tabindex="-1">常见问题（摘要） <a class="header-anchor" href="#常见问题-摘要" aria-label="Permalink to &quot;常见问题（摘要）&quot;">​</a></h2><p><strong>Q：MiniTavern Ultra 是什么？</strong><br> A：一款 AI 角色扮演聊天应用。可以一句话创建角色卡，或导入主流 v2 / v3 卡；用 GPT、Claude、OpenRouter 或本地模型对话，密钥和聊天优先留在本机。</p><p><strong>Q：数据会上传到你们服务器吗？</strong><br> A：聊天、角色与密钥等默认保存在本机；调用模型时请求发往你配置的第三方或本地地址。详见 <a href="/ultra_guides/privacy">隐私协议</a>。</p><p><strong>Q：没有 API 也能玩吗？</strong><br> A：需要自行准备云端 Key，或按 <a href="/ultra_guides/local/">部署本地模型</a> 在电脑上搭建后再连接手机。常见免费额度见 <a href="/ultra_guides/free-cloud/">免费云端</a>；本机生图见 <a href="/ultra_guides/local/image-gen/">生图模型部署</a>。</p><h2 id="下载与政策" tabindex="-1">下载与政策 <a class="header-anchor" href="#下载与政策" aria-label="Permalink to &quot;下载与政策&quot;">​</a></h2><ul><li>顶栏 <strong>下载 MiniTavern</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">产品官网</a></li><li><a href="/ultra_guides/privacy">隐私协议</a> · <a href="/ultra_guides/terms">服务条款</a></li></ul>',22)])])}const m=t(n,[["render",o]]);export{_ as __pageData,m as default};
